def transform(grid):
    h, w = len(grid), len(grid[0])

    row_lines = [(r, grid[r][0]) for r in range(h)
                 if all(x == grid[r][0] for x in grid[r])]
    col_lines = [(c, grid[0][c]) for c in range(w)
                 if all(grid[r][c] == grid[0][c] for r in range(h))]

    candidates = {color for _, color in row_lines + col_lines}
    if not candidates:
        return [row[:] for row in grid]

    # Separator lines are the solid-line color occurring least often;
    # this excludes uniform background rows in the first demonstration.
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    sep_color = min(candidates, key=lambda color: counts[color])

    row_seps = [r for r, color in row_lines if color == sep_color]
    col_seps = [c for c, color in col_lines if color == sep_color]

    def parts(size, seps):
        result, start = [], 0
        for p in seps:
            if start < p:
                result.append(list(range(start, p)))
            start = p + 1
        if start < size:
            result.append(list(range(start, size)))
        return result

    row_parts = parts(h, row_seps)
    col_parts = parts(w, col_seps)
    if not row_parts or not col_parts:
        return [row[:] for row in grid]

    rh, cw = len(row_parts[0]), len(col_parts[0])
    template = [[grid[row_parts[0][i]][col_parts[0][j]]
                 for j in range(cw)] for i in range(rh)]
    out = [row[:] for row in grid]
    for rp in row_parts:
        for cp in col_parts:
            for i, r in enumerate(rp):
                for j, c in enumerate(cp):
                    out[r][c] = template[i % rh][j % cw]
    return out
